INSERT INTO changelog (title, body, created_at) VALUES
('Диктування як у Claude: сірий текст, розділові знаки, правильні назви',
'Поки диктуєш — почуте видно сірим у полі; натиснув «стоп» — ШІ ставить розділові знаки, великі літери, виправляє явні помилки і пише власні назви точно (ProVector, імена клієнтів, стартапів, інструментів, кабінетів), і текст стає білим. Свої слова, які розпізнавання пише криво, — Налаштування → «Можливості» → «Словник для диктування». Тумблер «Причісувати надиктований текст» там же (≈0.1 цента за раз). Працює в чаті з Джері, у всіх полях з мікрофоном і при «затисни робота і говори».', '2026-11-01 16:00:00'),
('Задачі: потрібна папка клієнта сама',
'У вікні задачі замість загальної «Папки клієнта» — потрібна підпапка за змістом задачі: креативи/банери/сторіс → «Креативи», сайт/лендинг → «Сайт», звіти/цифри → «Дані і звіти», договори/рахунки → «Документи». Під нею — «уся папка клієнта». Посилання на ту саму папку більше не дублюються. Джері більше не додає папку клієнта в посилання задачі.', '2026-11-01 16:01:00');
